 1→package jlsm.engine.cluster.internal;
 2→
 3→import jlsm.engine.cluster.NodeAddress;
 4→
 5→import java.util.Objects;
 6→import java.util.concurrent.ConcurrentHashMap;
 7→
 8→/**
 9→ * Phi accrual failure detector for adaptive node liveness detection.
10→ *
11→ * <p>
12→ * Contract: Maintains a sliding window of heartbeat inter-arrival times per monitored node.
13→ * Computes phi = -log10(1 - CDF(timeSinceLastHeartbeat)) where CDF is based on a normal
14→ * distribution fitted to the heartbeat history. A higher phi value indicates a greater
15→ * likelihood that the node has failed. The detector is stateless for unknown nodes (returns
16→ * phi = 0.0 until at least two heartbeats have been recorded).
17→ *
18→ * <p>
19→ * Thread-safe: uses concurrent data structures for per-node state.
20→ *
21→ * <p>
22→ * Governed by: {@code .decisions/cluster-membership-protocol/adr.md}
23→ */
24→public final class PhiAccrualFailureDetector {
25→
26→    private final int windowSize;
27→    private final ConcurrentHashMap<NodeAddress, Object> heartbeatHistory =
28→            new ConcurrentHashMap<>();
29→
30→    /**
31→     * Creates a failure detector with the specified sliding window size.
32→     *
33→     * @param windowSize the maximum number of heartbeat intervals to retain; must be >= 2
34→     */
35→    public PhiAccrualFailureDetector(int windowSize) {
36→        if (windowSize < 2) {
37→            throw new IllegalArgumentException(
38→                    "windowSize must be >= 2, got: " + windowSize);
39→        }
40→        this.windowSize = windowSize;
41→    }
42→
43→    /**
44→     * Records a heartbeat from the specified node at the current time.
45→     *
46→     * @param from the address of the node that sent the heartbeat; must not be null
47→     */
48→    public void recordHeartbeat(NodeAddress from) {
49→        throw new UnsupportedOperationException("Not implemented");
50→    }
51→
52→    /**
53→     * Computes the current phi value for the specified node.
54→     *
55→     * @param node the address of the node to check; must not be null
56→     * @return the phi value; 0.0 if insufficient history
57→     */
58→    public double phi(NodeAddress node) {
59→        throw new UnsupportedOperationException("Not implemented");
60→    }
61→
62→    /**
63→     * Returns whether the specified node is considered available at the given threshold.
64→     *
65→     * @param node      the address of the node to check; must not be null
66→     * @param threshold the phi threshold above which the node is considered failed; must be positive
67→     * @return {@code true} if phi(node) is below the threshold
68→     */
69→    public boolean isAvailable(NodeAddress node, double threshold) {
70→        throw new UnsupportedOperationException("Not implemented");
71→    }
72→}
