16→/**
17→ * Rapid protocol implementation of {@link MembershipProtocol}.
18→ *
19→ * <p>
20→ * Contract: Implements the Rapid membership protocol with:
21→ * <ul>
22→ *   <li>Expander graph monitoring overlay (K observers per node)</li>
23→ *   <li>Multi-process cut detection (alerts from multiple observers before suspecting)</li>
24→ *   <li>Leaderless 75% consensus for view changes</li>
25→ *   <li>Adaptive phi accrual edge failure detection via {@link PhiAccrualFailureDetector}</li>
26→ * </ul>
27→ *
28→ * <p>
29→ * Uses {@link ClusterTransport} for messaging, {@link DiscoveryProvider} for bootstrap,
30→ * and {@link PhiAccrualFailureDetector} for edge failure detection.
31→ *
32→ * <p>
33→ * Side effects: Starts background threads for the protocol period loop. Modifies the
34→ * membership view on consensus. Notifies registered listeners of view changes.
35→ *
36→ * <p>
37→ * Governed by: {@code .decisions/cluster-membership-protocol/adr.md}
38→ */
39→public final class RapidMembership implements MembershipProtocol {
40→
41→    private final NodeAddress localAddress;
42→    private final ClusterTransport transport;
43→    private final DiscoveryProvider discovery;
44→    private final ClusterConfig config;
45→    private final PhiAccrualFailureDetector failureDetector;
46→    private final CopyOnWriteArrayList<MembershipListener> listeners = new CopyOnWriteArrayList<>();
47→
48→    private volatile MembershipView currentView;
49→    private volatile boolean started;
50→    private volatile boolean closed;
51→
52→    /**
53→     * Creates a new Rapid membership protocol instance.
54→     *
55→     * @param localAddress    the address of this node; must not be null
56→     * @param transport       the cluster transport; must not be null
57→     * @param discovery       the discovery provider; must not be null
58→     * @param config          the cluster configuration; must not be null
59→     * @param failureDetector the phi accrual failure detector; must not be null
60→     */
61→    public RapidMembership(NodeAddress localAddress, ClusterTransport transport,
62→            DiscoveryProvider discovery, ClusterConfig config,
63→            PhiAccrualFailureDetector failureDetector) {
64→        this.localAddress = Objects.requireNonNull(localAddress, "localAddress must not be null");
65→        this.transport = Objects.requireNonNull(transport, "transport must not be null");
66→        this.discovery = Objects.requireNonNull(discovery, "discovery must not be null");
67→        this.config = Objects.requireNonNull(config, "config must not be null");
68→        this.failureDetector = Objects.requireNonNull(failureDetector,
69→                "failureDetector must not be null");
70→    }
71→
72→    @Override
73→    public void start(List<NodeAddress> seeds) throws IOException {
74→        throw new UnsupportedOperationException("Not implemented");
75→    }
76→
77→    @Override
78→    public MembershipView currentView() {
79→        throw new UnsupportedOperationException("Not implemented");
80→    }
81→
82→    @Override
83→    public void addListener(MembershipListener listener) {
84→        throw new UnsupportedOperationException("Not implemented");
85→    }
86→
87→    @Override
88→    public void leave() throws IOException {
89→        throw new UnsupportedOperationException("Not implemented");
90→    }
91→
92→    @Override
93→    public void close() {
94→        throw new UnsupportedOperationException("Not implemented");
95→    }
96→}
