  1→package jlsm.engine.cluster;
  2→
  3→import java.time.Duration;
  4→import java.util.Objects;
  5→
  6→/**
  7→ * Configuration for cluster behavior including membership protocol tuning and timeouts.
  8→ *
  9→ * <p>
 10→ * Contract: Immutable configuration value created via {@link Builder}. All durations must be
 11→ * positive. The {@code consensusQuorumPercent} must be in range [1, 100]. Sensible defaults
 12→ * are provided by the builder.
 13→ *
 14→ * <p>
 15→ * Governed by: {@code .decisions/cluster-membership-protocol/adr.md},
 16→ * {@code .decisions/rebalancing-grace-period-strategy/adr.md}
 17→ *
 18→ * @param gracePeriod          time to wait before treating a departed node as permanent
 19→ * @param protocolPeriod       interval between membership protocol rounds
 20→ * @param pingTimeout          timeout for a single ping/ack exchange
 21→ * @param indirectProbes       number of indirect probe paths for failure detection
 22→ * @param phiThreshold         phi accrual failure detector threshold
 23→ * @param consensusQuorumPercent percentage of nodes required for view-change consensus
 24→ */
 25→public record ClusterConfig(Duration gracePeriod, Duration protocolPeriod, Duration pingTimeout,
 26→        int indirectProbes, double phiThreshold, int consensusQuorumPercent) {
 27→
 28→    /** Default grace period: 2 minutes. */
 29→    public static final Duration DEFAULT_GRACE_PERIOD = Duration.ofMinutes(2);
 30→
 31→    /** Default protocol period: 1 second. */
 32→    public static final Duration DEFAULT_PROTOCOL_PERIOD = Duration.ofSeconds(1);
 33→
 34→    /** Default ping timeout: 500 milliseconds. */
 35→    public static final Duration DEFAULT_PING_TIMEOUT = Duration.ofMillis(500);
 36→
 37→    /** Default indirect probes: 3. */
 38→    public static final int DEFAULT_INDIRECT_PROBES = 3;
 39→
 40→    /** Default phi threshold: 8.0. */
 41→    public static final double DEFAULT_PHI_THRESHOLD = 8.0;
 42→
 43→    /** Default consensus quorum: 75%. */
 44→    public static final int DEFAULT_CONSENSUS_QUORUM_PERCENT = 75;
 45→
 46→    public ClusterConfig {
 47→        Objects.requireNonNull(gracePeriod, "gracePeriod must not be null");
 48→        Objects.requireNonNull(protocolPeriod, "protocolPeriod must not be null");
 49→        Objects.requireNonNull(pingTimeout, "pingTimeout must not be null");
 50→        if (gracePeriod.isNegative() || gracePeriod.isZero()) {
 51→            throw new IllegalArgumentException("gracePeriod must be positive");
 52→        }
 53→        if (protocolPeriod.isNegative() || protocolPeriod.isZero()) {
 54→            throw new IllegalArgumentException("protocolPeriod must be positive");
 55→        }
 56→        if (pingTimeout.isNegative() || pingTimeout.isZero()) {
 57→            throw new IllegalArgumentException("pingTimeout must be positive");
 58→        }
 59→        if (indirectProbes < 0) {
 60→            throw new IllegalArgumentException(
 61→                    "indirectProbes must be non-negative, got: " + indirectProbes);
 62→        }
 63→        if (phiThreshold <= 0.0) {
 64→            throw new IllegalArgumentException(
 65→                    "phiThreshold must be positive, got: " + phiThreshold);
 66→        }
 67→        if (consensusQuorumPercent < 1 || consensusQuorumPercent > 100) {
 68→            throw new IllegalArgumentException(
 69→                    "consensusQuorumPercent must be in [1, 100], got: " + consensusQuorumPercent);
 70→        }
 71→    }
 72→
 73→    /**
 74→     * Returns a new builder with all defaults pre-populated.
 75→     *
 76→     * @return a new builder; never null
 77→     */
 78→    public static Builder builder() {
 79→        return new Builder();
 80→    }
 81→
 82→    /**
 83→     * Builder for {@link ClusterConfig} with sensible defaults.
 84→     */
 85→    public static final class Builder {
 86→
 87→        private Duration gracePeriod = DEFAULT_GRACE_PERIOD;
 88→        private Duration protocolPeriod = DEFAULT_PROTOCOL_PERIOD;
 89→        private Duration pingTimeout = DEFAULT_PING_TIMEOUT;
 90→        private int indirectProbes = DEFAULT_INDIRECT_PROBES;
 91→        private double phiThreshold = DEFAULT_PHI_THRESHOLD;
 92→        private int consensusQuorumPercent = DEFAULT_CONSENSUS_QUORUM_PERCENT;
 93→
 94→        private Builder() {}
 95→
 96→        public Builder gracePeriod(Duration gracePeriod) {
 97→            this.gracePeriod = Objects.requireNonNull(gracePeriod, "gracePeriod must not be null");
 98→            return this;
 99→        }
100→
101→        public Builder protocolPeriod(Duration protocolPeriod) {
102→            this.protocolPeriod = Objects.requireNonNull(protocolPeriod,
103→                    "protocolPeriod must not be null");
104→            return this;
105→        }
106→
107→        public Builder pingTimeout(Duration pingTimeout) {
108→            this.pingTimeout = Objects.requireNonNull(pingTimeout, "pingTimeout must not be null");
109→            return this;
110→        }
111→
112→        public Builder indirectProbes(int indirectProbes) {
113→            this.indirectProbes = indirectProbes;
114→            return this;
115→        }
116→
117→        public Builder phiThreshold(double phiThreshold) {
118→            this.phiThreshold = phiThreshold;
119→            return this;
120→        }
121→
122→        public Builder consensusQuorumPercent(int consensusQuorumPercent) {
123→            this.consensusQuorumPercent = consensusQuorumPercent;
124→            return this;
125→        }
126→
127→        /**
128→         * Builds the configuration.
129→         *
130→         * @return a new immutable {@link ClusterConfig}; never null
131→         */
132→        public ClusterConfig build() {
133→            return new ClusterConfig(gracePeriod, protocolPeriod, pingTimeout, indirectProbes,
134→                    phiThreshold, consensusQuorumPercent);
135→        }
136→    }
137→}
