 1→package jlsm.engine.cluster;
 2→
 3→import java.util.Objects;
 4→
 5→/**
 6→ * A cluster member with its address, lifecycle state, and incarnation number.
 7→ *
 8→ * <p>
 9→ * Contract: Immutable value type representing a node's membership information at a point
10→ * in time. The {@code incarnation} number is incremented by a node when it refutes suspicion,
11→ * allowing the protocol to distinguish stale failure reports from current ones.
12→ *
13→ * <p>
14→ * Governed by: {@code .decisions/cluster-membership-protocol/adr.md}
15→ *
16→ * @param address     the node's address; must not be null
17→ * @param state       the node's current membership state; must not be null
18→ * @param incarnation the node's incarnation number; must be non-negative
19→ */
20→public record Member(NodeAddress address, MemberState state, long incarnation) {
21→
22→    public Member {
23→        Objects.requireNonNull(address, "address must not be null");
24→        Objects.requireNonNull(state, "state must not be null");
25→        if (incarnation < 0) {
26→            throw new IllegalArgumentException(
27→                    "incarnation must be non-negative, got: " + incarnation);
28→        }
29→    }
30→}
