 1→package jlsm.engine.cluster;
 2→
 3→import java.util.Objects;
 4→
 5→/**
 6→ * A typed message exchanged between cluster nodes over the {@link ClusterTransport}.
 7→ *
 8→ * <p>
 9→ * Contract: Immutable value type encapsulating a message with its type, sender identity,
10→ * sequence number for deduplication/ordering, and an opaque payload. The payload format
11→ * is determined by the {@link MessageType}.
12→ *
13→ * <p>
14→ * Governed by: {@code .decisions/transport-abstraction-design/adr.md}
15→ *
16→ * @param type           the message type; must not be null
17→ * @param sender         the address of the sending node; must not be null
18→ * @param sequenceNumber monotonically increasing sequence for ordering; must be non-negative
19→ * @param payload        the message payload bytes; must not be null (may be empty)
20→ */
21→public record Message(MessageType type, NodeAddress sender, long sequenceNumber, byte[] payload) {
