  1→package jlsm.engine.cluster.internal;
  2→
  3→import jlsm.engine.cluster.NodeAddress;
  4→
  5→import java.util.Objects;
  6→import java.util.concurrent.ConcurrentHashMap;
  7→
  8→/**
  9→ * Phi accrual failure detector for adaptive node liveness detection.
 10→ *
 11→ * <p>
 12→ * Contract: Maintains a sliding window of heartbeat inter-arrival times per monitored node.
 13→ * Computes phi = -log10(1 - CDF(timeSinceLastHeartbeat)) where CDF is based on a normal
 14→ * distribution fitted to the heartbeat history. A higher phi value indicates a greater
 15→ * likelihood that the node has failed. The detector is stateless for unknown nodes (returns
 16→ * phi = 0.0 until at least two heartbeats have been recorded).
 17→ *
 18→ * <p>
 19→ * Thread-safe: uses concurrent data structures for per-node state.
 20→ *
 21→ * <p>
 22→ * Governed by: {@code .decisions/cluster-membership-protocol/adr.md}
 23→ */
 24→public final class PhiAccrualFailureDetector {
 25→
 26→    private final int windowSize;
 27→    private final ConcurrentHashMap<NodeAddress, HeartbeatHistory> heartbeatHistory =
 28→            new ConcurrentHashMap<>();
 29→
 30→    /**
 31→     * Creates a failure detector with the specified sliding window size.
 32→     *
 33→     * @param windowSize the maximum number of heartbeat intervals to retain; must be >= 2
 34→     */
 35→    public PhiAccrualFailureDetector(int windowSize) {
 36→        if (windowSize < 2) {
 37→            throw new IllegalArgumentException(
 38→                    "windowSize must be >= 2, got: " + windowSize);
 39→        }
 40→        this.windowSize = windowSize;
 41→    }
 42→
 43→    /**
 44→     * Records a heartbeat from the specified node at the current time.
 45→     *
 46→     * @param from the address of the node that sent the heartbeat; must not be null
 47→     */
 48→    public void recordHeartbeat(NodeAddress from) {
 49→        Objects.requireNonNull(from, "from must not be null");
 50→        final long now = System.nanoTime();
 51→        heartbeatHistory.compute(from, (key, existing) -> {
 52→            if (existing == null) {
 53→                return new HeartbeatHistory(windowSize, now);
 54→            }
 55→            existing.record(now);
 56→            return existing;
 57→        });
 58→    }
 59→
 60→    /**
 61→     * Computes the current phi value for the specified node.
 62→     *
 63→     * @param node the address of the node to check; must not be null
 64→     * @return the phi value; 0.0 if insufficient history
 65→     */
 66→    public double phi(NodeAddress node) {
 67→        Objects.requireNonNull(node, "node must not be null");
 68→        final HeartbeatHistory history = heartbeatHistory.get(node);
 69→        if (history == null || history.count() < 2) {
 70→            return 0.0;
 71→        }
 72→        final long now = System.nanoTime();
 73→        final long elapsed = now - history.lastHeartbeatNanos();
 74→        assert elapsed >= 0 : "elapsed time must be non-negative";
 75→
 76→        final double elapsedMs = elapsed / 1_000_000.0;
 77→        final double mean = history.mean();
 78→        final double stddev = history.stddev();
 79→
 80→        // Avoid division by zero: if stddev is essentially zero, use a small epsilon
 81→        final double effectiveStddev = Math.max(stddev, 0.1);
 82→
 83→        return computePhi(elapsedMs, mean, effectiveStddev);
 84→    }
 85→
 86→    /**
 87→     * Returns whether the specified node is considered available at the given threshold.
 88→     *
 89→     * @param node      the address of the node to check; must not be null
 90→     * @param threshold the phi threshold above which the node is considered failed; must be positive
 91→     * @return {@code true} if phi(node) is below the threshold
 92→     */
 93→    public boolean isAvailable(NodeAddress node, double threshold) {
 94→        Objects.requireNonNull(node, "node must not be null");
 95→        if (threshold <= 0.0) {
 96→            throw new IllegalArgumentException(
 97→                    "threshold must be positive, got: " + threshold);
 98→        }
 99→        return phi(node) < threshold;
100→    }
101→
102→    /**
103→     * Computes phi = -log10(1 - CDF(elapsed)) using a normal distribution
104→     * with the given mean and standard deviation.
105→     *
106→     * <p>The CDF is approximated using the complementary error function.
107→     */
108→    private static double computePhi(double elapsedMs, double mean, double stddev) {
109→        assert stddev > 0 : "stddev must be positive";
110→        // Compute the probability that the next heartbeat would arrive after 'elapsedMs'
111→        // P(X > elapsed) = 1 - CDF(elapsed) = 0.5 * erfc((elapsed - mean) / (stddev * sqrt(2)))
112→        final double y = (elapsedMs - mean) / stddev;
113→        final double pLate = 0.5 * erfc(y / Math.sqrt(2.0));
114→
115→        // phi = -log10(pLate)
116→        // Clamp pLate to avoid log(0) or negative phi
117→        if (pLate <= 0.0) {
118→            return Double.MAX_VALUE;
119→        }
120→        final double phi = -Math.log10(pLate);
121→        return Math.max(0.0, phi);
122→    }
123→
124→    /**
125→     * Approximation of the complementary error function erfc(x).
126→     * Uses Abramowitz and Stegun approximation 7.1.26, accurate to ~1.5e-7.
127→     */
128→    private static double erfc(double x) {
129→        // Handle negative x: erfc(-x) = 2 - erfc(x)
130→        if (x < 0) {
131→            return 2.0 - erfc(-x);
132→        }
133→        final double t = 1.0 / (1.0 + 0.3275911 * x);
134→        final double t2 = t * t;
135→        final double t3 = t2 * t;
136→        final double t4 = t3 * t;
137→        final double t5 = t4 * t;
138→        final double poly = 0.254829592 * t
139→                - 0.284496736 * t2
140→                + 1.421413741 * t3
141→                - 1.453152027 * t4
142→                + 1.061405429 * t5;
143→        return poly * Math.exp(-x * x);
144→    }
145→
146→    /**
147→     * Sliding window of heartbeat inter-arrival times for a single node.
148→     * Not thread-safe — callers must synchronize via ConcurrentHashMap.compute().
149→     */
150→    private static final class HeartbeatHistory {
151→        private final double[] intervals;
152→        private int head;
153→        private int size;
154→        private long lastNanos;
155→        private double sum;
156→        private double sumSquares;
157→
158→        HeartbeatHistory(int windowSize, long firstHeartbeatNanos) {
159→            assert windowSize >= 2 : "windowSize must be >= 2";
160→            this.intervals = new double[windowSize];
161→            this.head = 0;
162→            this.size = 0;
163→            this.lastNanos = firstHeartbeatNanos;
164→            this.sum = 0.0;
165→            this.sumSquares = 0.0;
166→        }
167→
168→        void record(long nowNanos) {
169→            final double intervalMs = (nowNanos - lastNanos) / 1_000_000.0;
170→            assert intervalMs >= 0 : "interval must be non-negative";
171→            lastNanos = nowNanos;
172→
173→            // If window is full, subtract the oldest value
174→            if (size == intervals.length) {
175→                final double oldest = intervals[head];
176→                sum -= oldest;
177→                sumSquares -= oldest * oldest;
178→            } else {
179→                size++;
180→            }
181→
182→            intervals[head] = intervalMs;
183→            sum += intervalMs;
184→            sumSquares += intervalMs * intervalMs;
185→            head = (head + 1) % intervals.length;
186→        }
187→
188→        int count() {
189→            // Number of intervals recorded (heartbeat count is intervals + 1,
190→            // but we need >= 2 heartbeats which means >= 1 interval)
191→            return size + 1; // +1 to account for the initial heartbeat
192→        }
193→
194→        long lastHeartbeatNanos() {
195→            return lastNanos;
196→        }
197→
198→        double mean() {
199→            assert size > 0 : "cannot compute mean with no intervals";
200→            return sum / size;
201→        }
202→
203→        double stddev() {
204→            assert size > 0 : "cannot compute stddev with no intervals";
205→            final double mean = mean();
206→            final double variance = (sumSquares / size) - (mean * mean);
207→            return Math.sqrt(Math.max(0.0, variance));
208→        }
209→    }
210→}
